const cfg = readConfig();
const pRes = await probe('proxy');
const bRes = await probe('backend');
const uRes = await probe('configuredUpstream');
const match = cfg.upstreamPort === cfg.backendPort;
const finding = match ? 'Upstream port matches backend port' : 'Upstream port mismatch: configured upstream port does not match backend port';
console.log(JSON.stringify({ config: cfg, proxy: pRes, backend: bRes, configuredUpstream: uRes, portMatch: match, finding: finding }));
